fn receiver_adjust(by_ref: bool, params: &[ast::TypeKind], owner: &str, by_self: bool) -> Option<ast::Adjust> {
    if params.len() == 0 {
        return None;
    }
    match ref_inner(&params[0]) {
        None => { if owns(&params[0], owner, by_self) { Some(ast::Adjust::Value) } else { None } },
        Some(inner) => { if !owns(&inner, owner, by_self) { None } else if by_ref { Some(ast::Adjust::Value) } else if types::is_ref_mut(&params[0]) { Some(ast::Adjust::RefMut) } else { Some(ast::Adjust::Ref) } },
    }
}

